1	package indexroom
2	
3	import (
4		"fmt"
5		"reflect"
6		"testing"
7	)
8	
9	// referenceScan independently computes the full filtered occurrence list and
10	// matched-block count for [from, to], the same way the old collectLocked did,
11	// so the page-sized scan can be compared against an oracle that keeps every
12	// record.
13	func referenceScan(index *Index, from, to int64, txIDs []string) ([]TxHit, int64) {
14		filter := map[string]struct{}{}
15		for _, id := range txIDs {
16			filter[id] = struct{}{}
17		}
18		var all []TxHit
19		var blocks int64
20		for height := from; height <= to; height++ {
21			block := index.Blocks[height]
22			matched := false
23			for position, tx := range block.Txs {
24				if len(txIDs) > 0 {
25					if _, ok := filter[tx]; !ok {
26						continue
27					}
28				}
